using System;using System.Linq;using System.Collections.Generic;using System.Text.Json;using MotorwaysSim;
class Trace{static void Main(string[] args){var d=JsonSerializer.Deserialize<CustomScenarioDefinition>(System.IO.File.ReadAllText(args[0]),new JsonSerializerOptions{IncludeFields=true,PropertyNameCaseInsensitive=true});var s=new CustomScenarioSession(d);var records=new List<object>();string previous="";var wall=System.Diagnostics.Stopwatch.StartNew();while(!s.Complete&&s.World.Time<150){if(wall.Elapsed.TotalSeconds>30)throw new Exception("Diagnostic30second wall cap");s.AdvanceTick();var w=s.World;string state=w.TripsCompleted+"/"+string.Join(";",w.Buildings.Where(b=>!b.IsHouse).Select(b=>b.Demand+":"+b.Reserved))+"/"+string.Join(";",w.Cars.Select(c=>c.ShopId+":"+c.Stage));if(state!=previous||w.TickCount%20==0){records.Add(new{w.Time,score=w.TripsCompleted,events=s.CompletedEvents,destinations=w.Buildings.Where(b=>!b.IsHouse).Select(b=>new{b.Id,b.Color,b.Demand,b.Reserved,b.Served,b.DemandCountdown}).ToArray(),cars=w.Cars.Select(c=>new{c.Id,c.HomeId,c.ShopId,stage=c.Stage.ToString(),c.ParkingSlot,c.Waiting,c.Obstacle,position=new[]{c.Position.X,c.Position.Y}}).ToArray()});previous=state;}}Console.WriteLine(JsonSerializer.Serialize(records));}}
